def test_negative_numbers():
    assert find_median_sorted_arrays([-3, -1], [-2, 0]) == -1.5


def test_one_element_each():
    assert find_median_sorted_arrays([5], [3]) == 4.0


def test_all_same():
    assert find_median_sorted_arrays([2, 2, 2], [2, 2, 2]) == 2.0

